// ── Enterprise Email Extractor for n8n Gmail Trigger ──

const item = $input.first().json;

// Generate Ticket ID
const ticketId = `PRC-${new Date().getFullYear()}-${Math.floor(100000 + Math.random() * 900000)}`;

// Extract fields directly from Gmail Trigger
const rawFrom =
  item.From ||
  item.from ||
  'user@example.com';

const emailSubject =
  item.Subject ||
  item.subject ||
  '(No Subject)';

const emailBody =
  item.snippet ||
  item.textPlain ||
  item.textHtml ||
  '';

// Default values
let emailSender = rawFrom;
let senderName = 'Unknown';

// Match: Name <email>
const match = rawFrom.match(/(.*)<(.*)>/);

if (match) {

  senderName = match[1]
    .trim()
    .replace(/"/g, '');

  emailSender = match[2]
    .trim()
    .replace('>', '');

} else {

  emailSender = rawFrom.trim();

  // Generate readable sender name
  senderName = emailSender
    .split('@')[0]
    .replace(/[._-]/g, ' ')
    .replace(/\b\w/g, c => c.toUpperCase());
}

// Dates
const receivedAt = item.internalDate
  ? new Date(Number(item.internalDate)).toISOString()
  : new Date().toISOString();

// IDs
const threadId =
  item.threadId ||
  `thread-${Date.now()}`;

const messageId =
  item.id ||
  `msg-${Date.now()}`;

return [{
  json: {

    ticket_id: ticketId,

    email_subject: emailSubject,

    email_body: emailBody,

    email_sender: emailSender,

    sender_name: senderName,

    received_at: receivedAt,

    thread_id: threadId,

    message_id: messageId
  }
}];

// ── Parse AI classification response ─────────────────────────────────────────
const inputData = $input.first().json;

let aiResponseText = '';
if (inputData.text)                                     aiResponseText = inputData.text;
else if (inputData.output)                              aiResponseText = inputData.output;
else if (inputData.content && Array.isArray(inputData.content))
  aiResponseText = inputData.content.map(c => c.text || '').join('');
else                                                    aiResponseText = JSON.stringify(inputData);

aiResponseText = aiResponseText.replace(/```json\n?/gi, '').replace(/```\n?/gi, '').trim();

let classification = {};
try {
  classification = JSON.parse(aiResponseText);
} catch (e) {
  classification = {
    category: 'General Inquiry', urgency: 'Medium', sentiment: 'Neutral',
    risk_level: 'Low', team: 'HelpDesk',
    summary: 'Unable to classify - requires manual review',
    keywords: [], requires_human: true, confidence: 0.0,
    suggested_customer_reply: 'Thank you for reaching out. A member of our team will review your request shortly.',
    internal_agent_note: 'Auto-classification failed. Requires manual review.',
    recommended_next_action: 'Manually review and assign ticket.'
  };
}

let emailFields = {};
try { emailFields = $('Extract Email & Ticket Details').first().json; } catch(e) { emailFields = {}; }

// ── Routing Engine ────────────────────────────────────────────────────────────
const category   = classification.category   || 'General Inquiry';
const urgency    = classification.urgency    || 'Low';
const risk       = classification.risk_level || 'Low';
const team       = classification.team       || 'HelpDesk';
const sentiment  = classification.sentiment  || 'Neutral';
const confidence = classification.confidence || 0.5;

const SLA_MAP = { Critical: 1, High: 4, Medium: 24, Low: 72 };

const QUEUE_MAP = {
  SupplierManagement: 'queue-supplier-mgmt',
  AccountsPayable   : 'queue-accounts-payable',
  Procurement       : 'queue-procurement',
  Legal             : 'queue-legal',
  Finance           : 'queue-finance',
  Compliance        : 'queue-compliance',
  HelpDesk          : 'queue-general'
};

const PRIORITY_SCORE = { Critical: 4, High: 3, Medium: 2, Low: 1 };

// Risk escalation override
let effectiveUrgency = urgency;
if (risk === 'High' && urgency !== 'Critical') effectiveUrgency = 'High';

// Sentiment-based escalation: Negative + High → escalate
if (sentiment === 'Negative' && effectiveUrgency === 'High') effectiveUrgency = 'Critical';
if (sentiment === 'Frustrated' && effectiveUrgency === 'High') effectiveUrgency = 'Critical';

// Low-confidence → manual review queue
let assignedTeam   = team;
let ticketStatus   = 'open';
if (confidence < 0.65) {
  classification.requires_human = true;
  assignedTeam  = 'HelpDesk';
  ticketStatus  = 'pending-human-review';
}

const needsEscalation = (effectiveUrgency === 'Critical') || (risk === 'High');

const slaDeadline = new Date(Date.now() + (SLA_MAP[effectiveUrgency] || 24) * 3600 * 1000).toISOString();

const output = {
  // Email fields
  ticket_id    : emailFields.ticket_id    || `PRC-${new Date().getFullYear()}-${Math.floor(100000+Math.random()*900000)}`,
  email_subject: emailFields.email_subject || '',
  email_body   : emailFields.email_body   || '',
  email_sender : emailFields.email_sender  || '',
  sender_name  : emailFields.sender_name   || '',
  received_at  : emailFields.received_at   || new Date().toISOString(),
  thread_id    : emailFields.thread_id     || '',
  message_id   : emailFields.message_id    || '',

  // Classification
  category    : category,
  urgency     : urgency,
  sentiment   : sentiment,
  risk_level  : risk,
  summary     : classification.summary  || '',
  keywords    : (classification.keywords || []).join(', '),
  requires_human: classification.requires_human || false,
  confidence  : confidence,

  // AI Copilot fields
  suggested_customer_reply  : classification.suggested_customer_reply   || '',
  internal_agent_note       : classification.internal_agent_note        || '',
  recommended_next_action   : classification.recommended_next_action    || '',

  // Routing decisions
  assigned_queue    : QUEUE_MAP[assignedTeam] || 'queue-general',
  assigned_team     : assignedTeam,
  effective_urgency : effectiveUrgency,
  sla_hours         : SLA_MAP[effectiveUrgency] || 24,
  sla_deadline      : slaDeadline,
  priority_score    : PRIORITY_SCORE[effectiveUrgency] || 2,
  needs_escalation  : needsEscalation,
  escalation_reason : needsEscalation ? `Urgency=${effectiveUrgency}, Risk=${risk}, Sentiment=${sentiment}` : null,

  // Ticket metadata
  ticket_status   : ticketStatus,
  auto_assigned   : confidence >= 0.75,
  routing_version : '2.0',
  routed_at       : new Date().toISOString()
};

return [{ json: output }];

